  const paths = {home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',symbols:'M7 3v18m-4-4 4 4 4-4M17 21V3m-4 4 4-4 4 4',trades:'M5 20V10m7 10V4m7 16v-7',tools:'M4 4h3v3H4zm7 0h3v3h-3zm7 0h3v3h-3zM4 11h3v3H4zm7 0h3v3h-3zm7 0h3v3h-3zM4 18h3v3H4zm7 0h3v3h-3zm7 0h3v3h-3z',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',back:'m15 4-8 8 8 8',close:'m6 6 12 12M18 6 6 18',plus:'M12 4v16M4 12h16',down:'m6 9 6 6 6-6'};
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.tools}"/></svg>`;
  const assets = '../../protected-assets/trading-platform/mobile-demo/';
