  function tradeChecks(v){const errors={};const validUnits=Number.isInteger(v.units)&&v.units>=5;const price=v.type==='entry'?v.entry:v.price;const margin=v.units*price/5;if(!validUnits)errors.units='Enter at least 5 whole units.';else if(margin>(v.availableMargin??6500))errors.units='You don’t have enough margin in your account.';if(!Number.isFinite(price)||price<=0)errors.entry='Enter a valid entry price.';for(const key of ['tp','sl']){if(v[key]){const rate=v[key+'Rate'];const direction=(v.side==='Buy'?1:-1)*(key==='tp'?1:-1);if(!Number.isFinite(rate)||rate<=0||(rate-price)*direction<(v.fx?.000009:.009999))errors[key]='Close rate must be '+(direction>0?'above':'below')+' the order price.';}}return {errors,margin,total:v.units*price};}
