  function depositMissing(values){
    const missing=[];
    if(!Number.isFinite(Number(values.amount))||Number(values.amount)<1||!Number.isInteger(Number(values.amount)))missing.push('a valid amount');
    if(values.method!=='card')return missing;
    if(!/^[0-9 ]+$/.test(values.card)||!/^\d{13,19}$/.test(values.card.replace(/ /g,'')))missing.push('card number');
    if(!values.name.trim())missing.push('name on card');
    const expiry=/^(0[1-9]|1[0-2])\/(\d{2})$/.exec(values.expiry);
    if(!expiry||2000+Number(expiry[2])<values.year||(2000+Number(expiry[2])===values.year&&Number(expiry[1])<values.month))missing.push('a valid expiration date');
    if(!/^\d{3,4}$/.test(values.cvv))missing.push('CVV');
    return missing;
  }
