    keyboard.innerHTML=`<div class="m-keyboard-toolbar"><span>${keyboardField.getAttribute('aria-label')||keyboardField.name}</span>${key('Done','done')}</div>${numeric?`<div class="m-numeric-keys">${['1','2','3','4','5','6','7','8','9'].map(n=>key(n)).join('')}${decimal?key('.','decimal','m-key-function'):key('Next','next','m-key-function')}${key('0')}${key('⌫','backspace','m-key-function')}</div>`:`<div class="m-letter-keys">${['qwertyuiop','asdfghjkl','zxcvbnm'].map((row,i)=>`<div class="m-key-row">${i===2?key('⇧','shift','m-key-function'):''}${[...row].map(c=>key(keyboardShift?c.toUpperCase():c)).join('')}${i===2?key('⌫','backspace','m-key-function'):''}</div>`).join('')}<div class="m-key-row m-key-bottom">${key('123','numbers','m-key-function')}${key('space','space','m-key-space')}${key('Next','next','m-key-function')}</div></div>`}<i class="m-keyboard-gesture"></i>`;
