    phone.append(backdrop,picker);
    const wheels=[...picker.querySelectorAll('.m-expiry-wheel')];
    function closePicker(){backdrop.remove();picker.remove();input.focus({preventScroll:true});}
    function sync(wheel){const options=[...wheel.children];const i=Math.max(0,Math.min(options.length-1,Math.round(wheel.scrollTop/32)));options.forEach((o,n)=>{o.setAttribute('aria-selected',String(n===i));o.style.setProperty('--wheel-distance',Math.min(3,Math.abs(n-i)));});wheel.setAttribute('aria-activedescendant',options[i].id);if(wheel===wheels[0])month=Number(options[i].dataset.value);else year=Number(options[i].dataset.value);}
    wheels[0].scrollTop=(month-1)*32;wheels[1].scrollTop=Math.max(0,years.indexOf(year))*32;
    wheels.forEach(wheel=>{sync(wheel);wheel.addEventListener('scroll',()=>sync(wheel),{passive:true});wheel.addEventListener('click',e=>{const option=e.target.closest('[role="option"]');if(option)wheel.scrollTo({top:[...wheel.children].indexOf(option)*32,behavior:'smooth'});});wheel.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const index=Math.round(wheel.scrollTop/32),last=wheel.children.length-1;const next=e.key==='Home'?0:e.key==='End'?last:Math.max(0,Math.min(last,index+(e.key==='ArrowDown'?1:-1)));wheel.scrollTo({top:next*32,behavior:'instant'});sync(wheel);}});});
